import sys
from bisect import bisect_left

def main():
    # Read all tokens from standard input efficiently
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    Q = int(input_data[1])

    # Parse sequence A
    A = [int(x) for x in input_data[2:N+2]]

    # Coordinate compression for unique values in A
    vals = sorted(set(A))
    M = len(vals)

    # bit_val stores the maximum LIS length for compressed values
    bit_val = [0] * (M + 1)
    dp = [0] * N

    # Calculate LIS ending exactly at each position i using a Fenwick tree
    for i in range(N):
        c = bisect_left(vals, A[i]) + 1

        # Query bit_val for max LIS length using values strictly less than A[i]
        res = 0
        idx = c - 1
        while idx > 0:
            if bit_val[idx] > res:
                res = bit_val[idx]
            idx -= idx & -idx

        cur_dp = res + 1
        dp[i] = cur_dp

        # Update bit_val with the new LIS length at position c
        idx = c
        while idx <= M:
            # Minor optimization: Break early if the new value isn't greater than the existing value,
            # avoiding unnecessary updates to parent nodes since we only care about maximums.
            if cur_dp > bit_val[idx]:
                bit_val[idx] = cur_dp
                idx += idx & -idx
            else:
                break

    # Parse and store queries
    queries = []
    idx_input = N + 2
    for qi in range(Q):
        r = int(input_data[idx_input])
        x = int(input_data[idx_input+1])
        idx_input += 2
        queries.append((x, r, qi))

    # Points hold properties of valid sequences: (value, original_position, lis_length)
    # Sort points by value ascending
    points = sorted((A[i], i + 1, dp[i]) for i in range(N))
    # Sort queries by x ascending to allow for two-pointer offline processing
    queries.sort()

    ans = [0] * Q
    # bit_pos stores the max LIS length corresponding to each sequence position
    bit_pos = [0] * (N + 1)
    p = 0

    # Answer queries offline
    for x, r, qi in queries:
        # Add all valid end-points into the position-based Fenwick tree
        # where the ending element is at most x
        while p < N and points[p][0] <= x:
            pos = points[p][1]
            length = points[p][2]

            # Update bit_pos with sequence length at position `pos`
            idx = pos
            while idx <= N:
                if length > bit_pos[idx]:
                    bit_pos[idx] = length
                    idx += idx & -idx
                else:
                    break

            p += 1

        # For the current query, find the max sequence length across positions 1..R
        res = 0
        idx = r
        while idx > 0:
            if bit_pos[idx] > res:
                res = bit_pos[idx]
            idx -= idx & -idx
        ans[qi] = res

    # Fast output
    sys.stdout.write("\n".join(map(str, ans)) + "\n")

